'use client';
import { ModalContextProps, ModalState } from "./type";
import React, { createContext, useState, useContext } from "react";

const ModalContext = createContext<ModalContextProps | undefined>(undefined);

export const useModal = () => {
  const context = useContext(ModalContext);
  if (!context) {
    throw new Error('useModal must be used within a ModalProvider');
  }
  return context;
};

export const ModalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [modal, setModal] = useState<ModalState>({open: false, id: null});

  const openModal = (id?: string | null) => {
    setModal({open: true, id: id || null});
  };

  const closeModal = () => {
    setModal({open: false, id: null});
  };

  const handleCloseModal = () => {
    setModal({open: false, id: null});
  };

  return (
    <ModalContext.Provider value={{ modal, openModal, closeModal, handleCloseModal }}>
      {children}
    </ModalContext.Provider>
  );
};

import React from 'react';

interface IndicatorProps {
  totalSteps: number;
  currentStep: number;
}

const Indicator: React.FC<IndicatorProps> = ({ totalSteps, currentStep }) => {
  return (
    <div className="flex justify-center space-x-2">
      {Array.from({ length: totalSteps }).map((_, step) => (
        <div
          key={step}
          className={`h-3 w-3 rounded-full ${
            step + 1 === currentStep ? "bg-black" : "bg-gray-300"
          }`}
        />
      ))}
    </div>
  );
};

export default Indicator;

"use client";
import { useModal } from "@/components/atom/modal/context";
import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { X } from 'lucide-react';


// Custom hook for managing body scroll
function useBodyScroll(open: boolean) {
  React.useEffect(() => {
    if (open) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [open]);
}

interface Props {
  content: React.ReactNode;
  sm?: boolean;
}

function Modal({ content, sm = false }: Props) {
  const { modal, closeModal } = useModal();
  useBodyScroll(modal.open);
  const [isMobile, setIsMobile] = useState(false);

  // Check if screen is mobile
  useEffect(() => {
    const checkIfMobile = () => {
      setIsMobile(window.innerWidth < 768);
    };

    // Initial check
    checkIfMobile();

    // Add event listener for window resize
    window.addEventListener('resize', checkIfMobile);

    // Cleanup event listener
    return () => window.removeEventListener('resize', checkIfMobile);
  }, []);



  return (
    <>
      {modal.open && (
        <>
          <div
            className="fixed inset-0 w-full h-screen bg-black bg-opacity-70"
            onClick={closeModal}
          />
          <div className="fixed inset-0 w-full h-screen z-50 flex justify-center items-center">
            <div 
              className={`relative z-50 bg-background ${
                sm 
                  ? isMobile
                    ? 'w-full h-screen px-20 py-4 overflow-auto'
                    : 'm-4 px-20 py-8 max-w-2xl w-[24rem] h-[24rem] rounded-lg' 
                  : 'w-full h-screen overflow-hidden px-20 py-4 sm:pt-14'
              }`}
            >
              {/* <Button 
                size='icon' 
                variant='outline' 
                className="rounded-full absolute top-4 right-4 z-10"
                onClick={closeModal}
              >
                <X className="h-5 w-5" />
              </Button> */}
              {content}
            </div>
          </div>
        </>
      )}
    </>
  );
}

export default Modal;

"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import Modal from "./modal";
import { useModal } from "./context";

interface RouteModalProps {
  content: React.ReactNode;
  returnTo: string;
  sm?: boolean;
}

export function RouteModal({ content, returnTo, sm = false }: RouteModalProps) {
  const { modal, openModal } = useModal();
  const router = useRouter();

  useEffect(() => {
    openModal();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!modal.open) {
      router.push(returnTo);
    }
  }, [modal.open, router, returnTo]);

  return <Modal content={content} sm={sm} />;
}

export default RouteModal;

